using McpServer;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;

var builder = Host.CreateApplicationBuilder(args);

// Register a named HttpClient — the MCP SDK resolves HttpClient from DI
// when instantiating tool classes, so IHttpClientFactory wiring is needed.
builder.Services.AddHttpClient<WeatherTools>(client =>
{
    client.DefaultRequestHeaders.UserAgent.ParseAdd("McpServer/1.0");
});

builder.Services
    .AddMcpServer()
    .WithStdioServerTransport()         // Communicate over stdin/stdout
    .WithToolsFromAssembly();            // Auto-discover [McpServerToolType] classes

await builder.Build().RunAsync();

